from collections import defaultdict

def solve(x):
    events = x.get('events', [])
    ticket_events = defaultdict(list)
    for event in events:
        ticket, rev, zone, grams, status = event
        ticket_events[ticket].append((rev, zone, grams, status))
    kept = []
    conflicts = []
    for ticket, events_list in ticket_events.items():
        sorted_events = sorted(events_list, key=lambda x: x[0], reverse=True)
        highest_rev = sorted_events[0][0]
        filtered_events = [e for e in sorted_events if e[0] == highest_rev]
        unique_events = []
        seen = set()
        for rev, zone, grams, status in filtered_events:
            key = (zone, grams, status)
            if key not in seen:
                seen.add(key)
                unique_events.append((rev, zone, grams, status))
        if len(unique_events) > 1:
            conflicts.append(ticket)
        else:
            valid_events = [(rev, zone, grams, status) for rev, zone, grams, status in unique_events if status != 'void']
            if valid_events:
                rev, zone, grams, status = valid_events[0]
                kept.append([ticket, rev, zone, grams])
    return {'kept': sorted(kept), 'conflicts': sorted(conflicts)}", _scope)
